 # Fixed external-only objective: mean dev local loss minus fixed-cache loss,
 # plus ten times mean absolute five-width exponent error vs generator median.
 dev_real={b:metrics(data[b][0]) for b in BOOKS};dev_fixed={b:models[b].core.logloss(data[b][0],WINDOW,.3) for b in BOOKS}
 for ci,c in enumerate(CANDIDATES):
  rows=[]
  for bi,b in enumerate(BOOKS):
   model=models[b];sample=[metrics(model.generate(N,c,100000+bi*1000+ci*10+i)) for i in range(DEV_DRAWS)]
   errors=[abs(dev_real[b][str(w)]['exponent']-statistics.median(r[str(w)]['exponent'] for r in sample)) for w in base.WIDTHS]
   ll=model.logloss(data[b][0],c);rows.append({'book':b,'bits_per_token':ll,'fixed_cache_bits_per_token':dev_fixed[b],'mean_absolute_taylor_error':statistics.mean(errors)})
