 out['selection']={'candidate_index':int(selected),'candidate':c,'rule':'min mean (dev loss − fixed-cache loss + 10 × mean absolute five-width dev exponent error); four simulated draws per book'}
 # Freeze the selected model, rules and external gate before inspecting any manuscript.
 for bi,b in enumerate(BOOKS):
  model=models[b];test=data[b][1];obs=metrics(test)
  generated=[metrics(model.generate(N,c,400000+bi*1000+i)) for i in range(TEST_DRAWS)]
  sh=[metrics(base.count_preserving_shuffle(test,seed=500000+bi*1000+i)) for i in range(NULL_DRAWS)]
  bg=[metrics(base.sample_empirical_bigram(test,n_tokens=N,seed=600000+bi*1000+i)) for i in range(NULL_DRAWS)]
  rows={}
  for width in base.WIDTHS:
   k=str(width);real=obs[k]['exponent'];vs=sorted(v[k]['exponent'] for v in generated);s=statistics.median(v[k]['exponent'] for v in sh);g=statistics.median(v[k]['exponent'] for v in bg)
   rows[k]={'observed':obs[k],'predictive_order4':vs[3],'predictive_order61':vs[60],
            'model_min':vs[0],'model_median':statistics.median(vs),'model_max':vs[-1],
            'shuffle_median':s,'bigram_median':g,'null_direction_gate':real>s and real>g,
            'predictive_interval_gate':vs[3]<=real<=vs[60]}
  ll=model.logloss(test,c);fixed=model.core.logloss(test,WINDOW,.3);zero=model.core.logloss(test,WINDOW,0.)
  local=ll<=fixed and ll<=zero
  out['test'][b]={'widths':rows,'selected_bits_per_token':ll,'fixed_cache_bits_per_token':fixed,'no_cache_bits_per_token':zero,'local_gate':local,
                  'joint_gate':local and all(x['null_direction_gate'] and x['predictive_interval_gate'] for x in rows.values())}
  print('finished',b,file=sys.stderr,flush=True)
